from pathlib import Path
import json
r=Path('docs/training/city-strategy-launch-2026-11-24');rows=json.loads((r/'run-register.json').read_text())
lines=['# Bounded training run ledger — 24 November 2026','','Generated from `run-register.json`. This is an alphabetical index; chronological decisions are in `training/EXPERIMENT_HISTORY.md`. Includes interrupted attempts and smoke checks. Saved decisions exclude unsaved work. Midgame continuations start after a recorded native prefix and are not full-start cities. Completed practice episodes can be one decision and are not full cities. Weights/binaries stay local-only. No eight-hour session has been launched.','','| Run | Status | Saved decisions | Completed cold cities | Completed midgame continuations | Completed practice episodes | Base LR | Horizon |','|---|---|---:|---:|---:|---:|---:|---:|']
for row in rows:
 c=row['config'];tasks=row.get('episodes_by_task',{});saves=row.get('checkpoints',[]);saved=max((s.get('added_decisions',0) for s in saves),default=0)
 lines.append(f"| {row['path'].replace('output/training/','')} | {row['status']} | {saved:,} | {tasks.get('city',{}).get('count',0)} | {tasks.get('city-recorded-start',{}).get('count',0)} | {sum(t['count'] for k,t in tasks.items() if k not in ('city','city-recorded-start'))} | {c.get('learning_rate','unrecorded')} | {c.get('horizon','inherited')} |")
lines+=['','## Main measured findings','','| Evidence | Result | Interpretation |','|---|---|---|','| Frozen new native skill cohort | Reservation7/64→32/64;priority67/128→128/128 | Learned skills generalize within these exercise families |','| Fresh road-only city confirmation04 | 85.95→86.19 on64 cities | No substantial city-score gain |','| City-only corrected-optimizer final | 78.22→89.76 on96 reused cities;reservation9/16→4/16 vs own start | Some development gain;skill tradeoff;no promotion |','| Opening-only final | 78.22→84.28 on96 reused cities | No substantial gain;established practice rows retained exactly |','| Bridge interface fix,same unchanged reference | 69.19→124.41 on32 reused cities;paired+55.22[34.03,76.16] | Engineering action-coverage gain,not PPO |','| Bridge-enabled longer PPO continuation | See current status and live run register | Bounded experiment;not a long launch |','','See `README.md`, `PLAN.md`, and the measurement JSON files for checkpoint hashes, exact comparisons, limits, failed hypotheses and superseding decisions. The normalized bridge-choice prototype is unused.','']
(r/'RUN_LEDGER.md').write_text('\n'.join(lines))
